/** static u32 CanTradeSelectedMon(struct Pokemon *playerParty, int partyCount, int monIdx) */
export function CanTradeSelectedMon(playerParty: any, partyCount: any, monIdx: any): any {
  let i, numMonsLeft;
      let partner: any = null;
      let species: any = [];
      let species2: any = [];

      for (i = 0; i < partyCount; i++)
      {
          species2[i] = GetMonData(playerParty[i], MON_DATA_SPECIES_OR_EGG);
          species[i] = GetMonData(playerParty[i], MON_DATA_SPECIES);
      }

       
      if (!IsNationalPokedexEnabled())
      {
          if (species2[monIdx] == (412))
              return (3);

          if (!IsSpeciesInHoennDex(species2[monIdx]))
              return (2);
      }

      partner =gLinkPlayers[GetMultiplayerId() ^ 1];
      if ((partner.version & 0xFF) != (2) &&
          (partner.version & 0xFF) != (1))
      {
           
          if (!(partner.progressFlagsCopy & 0xF))
          {
              if (species2[monIdx] == (412))
                  return (5);

              if (!IsSpeciesInHoennDex(species2[monIdx]))
                  return (4);
          }
      }

      if (species[monIdx] == (410) || species[monIdx] == (151))
      {
          if (!GetMonData(playerParty[monIdx], MON_DATA_MODERN_FATEFUL_ENCOUNTER))
              return (4);
      }

       
      for (i = 0; i < partyCount; i++)
      {
          if (species2[i] == (412))
              species2[i] = (0);
      }

       
      for (numMonsLeft = 0, i = 0; i < partyCount; i++)
      {
          if (i != monIdx)
              numMonsLeft += species2[i];
      }

      if (numMonsLeft != 0)
          return (0);
      else
          return (1);
}

/** s32 GetGameProgressForLinkTrade(void) */
export function GetGameProgressForLinkTrade(): any {
  let versionId: any = null;  
      let version: any = null;

      if (gReceivedRemoteLinkPlayers)
      {
          versionId = 0;
          version = (gLinkPlayers[GetMultiplayerId() ^ 1].version & 0xFF);

          if (version == (2) || version == (1) || version == (3))
              versionId = 0;
          else if (version == (4) || version == (5))
              versionId = 2;

           
          if (versionId > 0)
          {
               
              if (gLinkPlayers[GetMultiplayerId()].progressFlagsCopy & 0xF0)
              {
                  if (versionId == 2)  
                  {
                       
                      if (gLinkPlayers[GetMultiplayerId() ^ 1].progressFlagsCopy & 0xF0)
                          return (0);
                      else
                          return (2);
                  }
              }
              else
              {
                  return (1);
              }
          }
      }
      return (0);
}

/** static bool32 IsDeoxysOrMewUntradable(u16 species, bool8 isModernFatefulEncounter) */
export function IsDeoxysOrMewUntradable(species: any, isModernFatefulEncounter: any): any {
  if (species == (410) || species == (151))
      {
          if (!isModernFatefulEncounter)
              return TRUE;
      }
      return FALSE;
}

/** int GetUnionRoomTradeMessageId(struct RfuGameCompatibilityData player, struct RfuGameCompatibilityData partner, u16 playerSpecies2, u16 partnerSpecies, u8 requestedType, u16 playerSpecies, bool8 isModernFatefulEncounter) */
export function GetUnionRoomTradeMessageId(player: any, partner: any, playerSpecies2: any, partnerSpecies: any, requestedType: any, playerSpecies: any, isModernFatefulEncounter: any): any {
  let playerHasNationalDex: any = player.hasNationalDex;
      let playerCanLinkNationally: any = player.canLinkNationally;
      let partnerHasNationalDex: any = partner.hasNationalDex;
      let partnerCanLinkNationally: any = partner.canLinkNationally;
      let partnerVersion: any = partner.version;

       
       
      if (partnerVersion != (3))
      {
          if (!playerCanLinkNationally)
              return (8);
          else if (!partnerCanLinkNationally)
              return (9);
      }

       
      if (IsDeoxysOrMewUntradable(playerSpecies, isModernFatefulEncounter))
          return (4);

      if (partnerSpecies == (412))
      {
           
          if (playerSpecies2 != partnerSpecies)
              return (2);
      }
      else
      {
           
          if (gSpeciesInfo[playerSpecies2].types[0] != requestedType
           && gSpeciesInfo[playerSpecies2].types[1] != requestedType)
              return (1);
      }

       
       
      if (playerSpecies2 == (412) && playerSpecies2 != partnerSpecies)
          return (3);

       
      if (!playerHasNationalDex)
      {
          if (playerSpecies2 == (412))
              return (6);

          if (!IsSpeciesInHoennDex(playerSpecies2))
              return (4);

          if (!IsSpeciesInHoennDex(partnerSpecies))
              return (5);
      }

       
      if (!partnerHasNationalDex && !IsSpeciesInHoennDex(playerSpecies2))
          return (7);

       
      return (0);
}

/** int CanRegisterMonForTradingBoard(struct RfuGameCompatibilityData player, u16 species2, u16 species, bool8 isModernFatefulEncounter) */
export function CanRegisterMonForTradingBoard(player: any, species2: any, species: any, isModernFatefulEncounter: any): any {
  let hasNationalDex: any = player.hasNationalDex;

      if (IsDeoxysOrMewUntradable(species, isModernFatefulEncounter))
          return (1);

      if (hasNationalDex)
          return (0);

       
      if (species2 == (412))
          return (2);

      if (IsSpeciesInHoennDex(species2))
          return (0);

      return (1);
}

/** int CanSpinTradeMon(struct Pokemon *mon, u16 monIdx) */
export function CanSpinTradeMon(mon: any, monIdx: any): any {
  let i, version, versions, canTradeAnyMon, numMonsLeft;
      let speciesArray: any = [];

       
      for (i = 0; i < gPlayerPartyCount; i++)
      {
          speciesArray[i] = GetMonData(mon[i], MON_DATA_SPECIES_OR_EGG);
          if (speciesArray[i] == (412))
              speciesArray[i] = (0);
      }

      versions = 0;
      canTradeAnyMon = TRUE;
      for (i = 0; i < GetLinkPlayerCount(); i++)
      {
          version = gLinkPlayers[i].version & 0xFF;
          if (version == (4) ||
              version == (5))
              versions = 0;
          else
              versions |= 1;
      }

      for (i = 0; i < GetLinkPlayerCount(); i++)
      {
          let player: any =gLinkPlayers[i];

           
          do
          {
              if (!(player.progressFlags & 0xF))
                  canTradeAnyMon = FALSE;

              if (versions && (player.progressFlags / 16))
                  canTradeAnyMon = FALSE;
          } while (0);
      }

      if (canTradeAnyMon == FALSE)
      {
          if (!IsSpeciesInHoennDex(speciesArray[monIdx]))
              return (2);

          if (speciesArray[monIdx] == (0))
              return (3);
      }

      numMonsLeft = 0;
      for (i = 0; i < gPlayerPartyCount; i++)
      {
          if (monIdx != i)
              numMonsLeft += speciesArray[i];
      }

      if (!numMonsLeft)
          return (1);
      else
          return (0);
}

