/** static void TradeMons(u8 playerPartyIdx, u8 partnerPartyIdx) */
export function TradeMons(playerPartyIdx: any, partnerPartyIdx: any): any {
  let friendship: any = null;

      let playerMon: any =gPlayerParty[playerPartyIdx];
      let playerMail: any = GetMonData(playerMon, MON_DATA_MAIL);

      let partnerMon: any =gEnemyParty[partnerPartyIdx];
      let partnerMail: any = GetMonData(partnerMon, MON_DATA_MAIL);

       
      if (playerMail != (0xFF))
          ClearMail(gSaveBlock1Ptr.mail[playerMail]);

      SWAP(playerMon, partnerMon, sTradeAnim.tempMon);

       
       
      friendship = 70;
      if (!GetMonData(playerMon, MON_DATA_IS_EGG))
          SetMonData(playerMon, MON_DATA_FRIENDSHIP,friendship);

      if (partnerMail != (0xFF))
          GiveMailToMon(playerMon,gTradeMail[partnerMail]);

      UpdatePokedexForReceivedMon(playerPartyIdx);
      if (gReceivedRemoteLinkPlayers)
          TryEnableNationalDexFromLinkPartner();
}

