          DmaCopyLarge16(3, gTradeGba_Gfx, BG_CHAR_ADDR(0), 0x1420, 0x1000);
          SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_MODE_0 |
                                        DISPCNT_OBJ_1D_MAP |
                                        DISPCNT_BG1_ON |
                                        DISPCNT_OBJ_ON);
