              SetGpuReg(REG_OFFSET_BLDCNT, BLDCNT_TGT1_BG1 |
                                           BLDCNT_TGT1_OBJ |
                                           BLDCNT_EFFECT_BLEND |
                                           BLDCNT_TGT2_BG2);
              SetGpuReg(REG_OFFSET_BLDALPHA, BLDALPHA_BLEND(16, 4));

               
              CreateTask(Task_AnimateWirelessSignal, 5);
