          gSprites[sTradeAnim.monSpriteIds[(1)]].y = gMonFrontPicCoords[sTradeAnim.monSpecies[(1)]].y_offset + 60;
          gSprites[sTradeAnim.monSpriteIds[(1)]].x2 = 0;
          gSprites[sTradeAnim.monSpriteIds[(1)]].y2 = 0;
