          CreatePokeballSpriteToReleaseMon(sTradeAnim.monSpriteIds[(1)], gSprites[sTradeAnim.monSpriteIds[(1)]].oam.paletteNum, 120, 84, 2, 1, 20, (0x0000FFFF) | (0xF << 16), sTradeAnim.monSpecies[(1)]);
