/** static void CB2_UpdateLinkTrade(void) */
export function CB2_UpdateLinkTrade(): any {
  if (DoTradeAnim() == TRUE)
      {
          DestroySprite(gSprites[sTradeAnim.monSpriteIds[(0)]]);
          FreeSpriteOamMatrix(gSprites[sTradeAnim.monSpriteIds[(1)]]);
          TradeMons(gSelectedTradeMonPositions[(0)], gSelectedTradeMonPositions[(1)] % (6));
          if (!IsWirelessTrade())
          {
              sTradeAnim.linkData[0] = (0xABCD);
              sTradeAnim.scheduleLinkTransfer = 1;
          }
          SetMainCallback2(CB2_WaitTradeComplete);
      }
      HandleLinkDataSend();
      HandleLinkDataReceive();
      RunTasks();
      RunTextPrinters();
      AnimateSprites();
      BuildOamBuffer();
      UpdatePaletteFade();
}

/** static void CB2_WaitTradeComplete(void) */
export function CB2_WaitTradeComplete(): any {
  let mpId: any = TradeGetMultiplayerId();
      if (IsWirelessTrade())
      {
          SetMainCallback2(CB2_TryLinkTradeEvolution);
      }
      else
      {
          HandleLinkDataReceive();
          if (mpId == 0
              && sTradeAnim.playerFinishStatus == STATUS_READY
              && sTradeAnim.partnerFinishStatus == STATUS_READY)
          {
              sTradeAnim.linkData[0] = (0xDCBA);
              SendBlock(BitmaskAllOtherLinkPlayers(), sTradeAnim.linkData, sizeof(sTradeAnim.linkData));
              sTradeAnim.playerFinishStatus = STATUS_CANCEL;
              sTradeAnim.partnerFinishStatus = STATUS_CANCEL;
          }
      }
      RunTasks();
      AnimateSprites();
      BuildOamBuffer();
      UpdatePaletteFade();
}

/** static void CB2_SaveAndEndTrade(void) */
export function CB2_SaveAndEndTrade(): any {
  switch (gMain.state)
      {
      case 0:
          gMain.state++;
          StringExpandPlaceholders(gStringVar4, gText_CommunicationStandby5);
          DrawTextOnTradeWindow(0, gStringVar4, 0);
          break;
      case 1:
          SetTradeLinkStandbyCallback(0);
          gMain.state = 100;
          sTradeAnim.timer = 0;
          break;
      case 100:
          if (++sTradeAnim.timer > 180)
          {
              gMain.state = 101;
              sTradeAnim.timer = 0;
          }
          if (_IsLinkTaskFinished())
              gMain.state = 2;
          break;
      case 101:
          if (_IsLinkTaskFinished())
              gMain.state = 2;
          break;
      case 2:
          gMain.state = 50;
          StringExpandPlaceholders(gStringVar4, gText_SavingDontTurnOffPower);
          DrawTextOnTradeWindow(0, gStringVar4, 0);
          break;
      case 50:
          if (!InUnionRoom())
              IncrementGameStat((21));
          if (gWirelessCommType)
              MysteryGift_TryIncrementStat((2), gLinkPlayers[GetMultiplayerId() ^ 1].trainerId);

          SetContinueGameWarpStatusToDynamicWarp();
          LinkFullSave_Init();
          gMain.state++;
          sTradeAnim.timer = 0;
          break;
      case 51:
          if (++sTradeAnim.timer == 5)
              gMain.state++;
          break;
      case 52:
          if (LinkFullSave_WriteSector())
          {
              ClearContinueGameWarpStatus2();
              gMain.state = 4;
          }
          else
          {
               
              sTradeAnim.timer = 0;
              gMain.state = 51;
          }
          break;
      case 4:
          LinkFullSave_ReplaceLastSector();
          gMain.state = 40;
          sTradeAnim.timer = 0;
          break;
      case 40:
          if (++sTradeAnim.timer > 50)
          {
              if (GetMultiplayerId() == 0)
                  sTradeAnim.timer = Random() % 30;
              else
                  sTradeAnim.timer = 0;
              gMain.state = 41;
          }
          break;
      case 41:
          if (sTradeAnim.timer == 0)
          {
              SetTradeLinkStandbyCallback(1);
              gMain.state = 42;
          }
          else
          {
              sTradeAnim.timer--;
          }
          break;
      case 42:
          if (_IsLinkTaskFinished())
          {
              LinkFullSave_SetLastSectorSignature();
              gMain.state = 5;
          }
          break;
      case 5:
          if (++sTradeAnim.timer > 60)
          {
              gMain.state++;
              SetTradeLinkStandbyCallback(2);
          }
          break;
      case 6:
          if (_IsLinkTaskFinished())
          {
              BeginNormalPaletteFade((((0x0000FFFF) | (0xFFFF0000))), 0, 0, 16, (RGB(0, 0, 0)));
              gMain.state ++;
          }
          break;
      case 7:
          if (!gPaletteFade.active)
          {
              FadeOutBGM(3);
              gMain.state++;
          }
          break;
      case 8:
          if (IsBGMStopped() == TRUE)
          {
              if (gWirelessCommType && gMain.savedCallback == CB2_StartCreateTradeMenu)
                  SetTradeLinkStandbyCallback(3);
              else
                  SetCloseLinkCallback();
              gMain.state++;
          }
          break;
      case 9:
          if (gWirelessCommType && gMain.savedCallback == CB2_StartCreateTradeMenu)
          {
              if (_IsLinkTaskFinished())
              {
                  gSoftResetDisabled = FALSE;
                  SetMainCallback2(CB2_FreeTradeAnim);
              }
          }
          else if (!gReceivedRemoteLinkPlayers)
          {
              gSoftResetDisabled = FALSE;
              SetMainCallback2(CB2_FreeTradeAnim);
          }
          break;
      }
      if (!HasLinkErrorOccurred())
      {
          RunTasks();
      }
      AnimateSprites();
      BuildOamBuffer();
      UpdatePaletteFade();
}

/** static void CB2_FreeTradeAnim(void) */
export function CB2_FreeTradeAnim(): any {
  if (!gPaletteFade.active)
      {
          FreeAllWindowBuffers();
          Free(GetBgTilemapBuffer(3));
          Free(GetBgTilemapBuffer(1));
          Free(GetBgTilemapBuffer(0));
          FreeMonSpritesGfx();
          FREE_AND_SET_NULL(sTradeAnim);
          if (gWirelessCommType)
              DestroyWirelessStatusIndicatorSprite();
          SetMainCallback2(gMain.savedCallback);
      }
      RunTasks();
      AnimateSprites();
      BuildOamBuffer();
      UpdatePaletteFade();
}

